PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS hospitals (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    type TEXT NOT NULL DEFAULT 'AE',
    address TEXT,
    city TEXT,
    postcode TEXT,
    phone TEXT,
    website TEXT,
    lat REAL,
    lng REAL,
    region TEXT,
    country TEXT NOT NULL,
    opening_hours TEXT,
    image_url TEXT,
    aliases TEXT,
    about_text TEXT,
    departments TEXT,
    trust_id TEXT NOT NULL REFERENCES trusts(id),
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now'))
  );
INSERT OR IGNORE INTO hospitals VALUES('be724f4b-477f-4e82-9b72-720f6243ab48','Wrexham Maelor Hospital','wrexham-maelor-hospital','AE',NULL,'Wrexham','LL13 7TD',NULL,NULL,53.04599999999999938,-2.991999999999999993,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/7/7f/Ysbyty_Maelor_Wrecsam._%28Wrexham_Maelor_Hospital%29_-_geograph.org.uk_-_161697.jpg','Ysbyty Maelor Wrecsam, Wrexham A&E','Wrexham Maelor Hospital is a district general hospital located in Wrexham, North Wales. It is managed by Betsi Cadwaladr University Health Board and serves a population of approximately 240,000 people across Wrexham, Flintshire and surrounding areas. The hospital''s Emergency Department (A&E) operates 24 hours a day, 7 days a week, and handles around 70,000 attendances per year. The department has recently undergone refurbishment to improve patient flow and waiting areas. Wrexham Maelor is one of three major hospitals in the Betsi Cadwaladr area, alongside Ysbyty Gwynedd in Bangor and Glan Clwyd Hospital in Bodelwyddan.','["Emergency Department (A&E)","Acute Medical Unit","Critical Care","Cardiology","Orthopaedics","General Surgery","Paediatrics","Maternity","Radiology","Pathology"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('2ae5855e-af31-4462-8ba5-87dedea735f9','The Grange University Hospital','the-grange-university-hospital','AE',NULL,'Llanfrechfa','NP44 8YN',NULL,NULL,51.63600000000000278,-3.025999999999999802,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/The_Grange_University_Hospital%2C_Llanfrechfa_%28geograph_6872256%29.jpg/960px-The_Grange_University_Hospital%2C_Llanfrechfa_%28geograph_6872256%29.jpg','Grange Hospital, Ysbyty Prifysgol y Faenor','The Grange University Hospital is a specialist and critical care centre in Llanfrechfa, Cwmbran, which opened in November 2020. It is the newest major hospital in Wales and is managed by Aneurin Bevan University Health Board. The hospital replaced the Royal Gwent Hospital as the main emergency department for the region, serving over 600,000 people across Gwent. The state-of-the-art facility cost approximately £350 million and features modern emergency care facilities, critical care units, and specialist services. It is designed to handle the most serious emergencies in the region.','["Emergency Department (A&E)","Critical Care Unit","Major Trauma","Acute Medicine","General Surgery","Cardiology","Respiratory Medicine","Neurology","Radiology","Pathology"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('2104e4f2-4c3e-41bf-95f7-aa445c7d120c','Glangwili General Hospital','glangwili-general-hospital','AE',NULL,'Carmarthen','SA31 2AF',NULL,NULL,51.86399999999999722,-4.306000000000000049,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/d/d3/West_Wales_General_Hospital%2C_Glangwili%2C_Carmarthen_-_geograph.org.uk_-_21092.jpg','Glangwili Hospital, West Wales General Hospital','Glangwili General Hospital is a district general hospital in Carmarthen, West Wales, managed by Hywel Dda University Health Board. The hospital serves the communities of Carmarthenshire and parts of Ceredigion and Pembrokeshire, covering a large rural area of West Wales. The A&E department provides 24-hour emergency care and sees approximately 45,000 patients per year. The hospital also offers a range of specialist services including maternity, paediatrics, and surgical care. Due to the rural nature of the area, many patients travel significant distances to reach the hospital.','["Emergency Department (A&E)","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Radiology","Pathology","Elderly Care"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('3bc9a242-05ec-44c3-8c35-b6deb40e0012','Prince Charles Hospital','prince-charles-hospital','AE',NULL,'Merthyr Tydfil','CF47 9DT',NULL,NULL,51.74699999999999989,-3.382000000000000117,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Prince_Charles_Hospital_Rear.jpg/960px-Prince_Charles_Hospital_Rear.jpg','PCH, Prince Charles A&E Merthyr','Prince Charles Hospital is a district general hospital in Merthyr Tydfil, South Wales. Managed by Cwm Taf Morgannwg University Health Board, it serves the population of Merthyr Tydfil, Cynon Valley, and surrounding areas. The Emergency Department handles approximately 55,000 attendances annually and is one of the busier A&E departments in the Welsh valleys. The hospital provides a full range of acute services and has undergone significant investment in recent years to modernise its facilities and improve emergency care pathways.','["Emergency Department (A&E)","Acute Medical Unit","General Surgery","Orthopaedics","Paediatrics","Maternity","Cardiology","Respiratory Medicine","Radiology"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('23d746b5-2810-4f49-95af-adf0340b88f2','Morriston Hospital','morriston-hospital','AE',NULL,'Swansea','SA6 6NL',NULL,NULL,51.67399999999999949,-3.934000000000000163,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/4/44/Ysbyty_Treforys._Morriston_Hospital._-_geograph.org.uk_-_404965.jpg','Ysbyty Treforys, Morriston A&E','Morriston Hospital is a large teaching hospital in the Morriston area of Swansea, managed by Swansea Bay University Health Board. It is the main hospital for emergency and acute services in the Swansea area, serving a population of around 390,000 people. The Emergency Department sees approximately 90,000 patients per year, making it one of the busiest in Wales. Morriston Hospital is also a regional centre for burns and plastic surgery, cardiac surgery, and renal services. The hospital has over 700 beds and is one of the largest hospitals in Wales.','["Emergency Department (A&E)","Major Trauma","Burns & Plastic Surgery","Cardiac Surgery","Renal Medicine","Critical Care","General Surgery","Orthopaedics","Respiratory Medicine","Radiology"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('7451a406-e91b-4844-879e-2c451bb89867','University Hospital of Wales','university-hospital-of-wales','AE',NULL,'Cardiff','CF14 4XW',NULL,NULL,51.50600000000000022,-3.189000000000000056,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/University_Hospital_of_Wales%2C_Heath_Park_-_Cardiff_-_geograph.org.uk_-_1736088.jpg/960px-University_Hospital_of_Wales%2C_Heath_Park_-_Cardiff_-_geograph.org.uk_-_1736088.jpg','UHW, Heath Hospital, Cardiff A&E','University Hospital of Wales (UHW) is the largest hospital in Wales, located in the Heath area of Cardiff. Managed by Cardiff and Vale University Health Board, it is a major teaching hospital and tertiary referral centre serving the population of Cardiff, the Vale of Glamorgan, and wider South Wales. The Emergency Department is one of the busiest in the UK, handling over 100,000 attendances per year. UHW is a major trauma centre for South and West Wales and provides specialist services in neurosurgery, cardiac surgery, transplant, and paediatric intensive care. The hospital has approximately 1,000 beds.','["Emergency Department (A&E)","Major Trauma Centre","Neurosurgery","Cardiac Surgery","Transplant","Paediatric Intensive Care","Critical Care","Oncology","Haematology","Radiology","Pathology"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('4d9e094e-341e-4545-8f7c-98f0d3ea1d69','Ysbyty Gwynedd','ysbyty-gwynedd','AE',NULL,'Bangor','LL57 2PW',NULL,NULL,53.22800000000000153,-4.136999999999999566,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/5/58/Ysbyty_Gwynedd%2C_Bangor.jpg','Gwynedd Hospital, Bangor Hospital','Ysbyty Gwynedd is a district general hospital in Bangor, North Wales, managed by Betsi Cadwaladr University Health Board. The hospital serves the population of Gwynedd and Anglesey, an area covering approximately 130,000 people across a large rural and mountainous region. The A&E department provides 24-hour emergency care and handles around 40,000 attendances per year. Due to its location, the hospital serves as a critical access point for emergency care in northwest Wales, with some patients travelling significant distances from remote communities. The hospital also works closely with mountain rescue and coastguard services.','["Emergency Department (A&E)","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Radiology","Elderly Care"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('e490bfcd-1b96-4f1c-9ddb-358fd31c9ca9','Glan Clwyd Hospital','glan-clwyd-hospital','AE',NULL,'Bodelwyddan','LL18 5UJ',NULL,NULL,53.27199999999999847,-3.494000000000000216,'Wales','Wales','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/b/b5/The_new_facade_at_Ysbyty_Glan_Clwyd_2018_%28geograph_5882700%29.jpg','Ysbyty Glan Clwyd, Bodelwyddan Hospital','Glan Clwyd Hospital (Ysbyty Glan Clwyd) is a district general hospital in Bodelwyddan, Denbighshire, North Wales. Managed by Betsi Cadwaladr University Health Board, the hospital serves the communities of Conwy, Denbighshire and surrounding areas. The Emergency Department provides 24-hour care and sees approximately 50,000 attendances per year. The hospital underwent a major redevelopment project completed in 2019, which included significant improvements to the emergency department, critical care facilities, and the main entrance. The hospital is one of three acute sites within the Betsi Cadwaladr Health Board area.','["Emergency Department (A&E)","Acute Medicine","Critical Care","General Surgery","Orthopaedics","Paediatrics","Maternity","Cardiology","Radiology"]','d45f3247-5598-4638-853b-17e269d3d9d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('4e2e0007-d790-4b21-8659-2338d20dccf2','Royal London Hospital','royal-london-hospital','AE',NULL,'London','E1 1FR','020 7377 7000',NULL,51.51800000000000068,-0.05800000000000000294,'London','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Royal_London_Hospital_redevelopment.jpg/960px-Royal_London_Hospital_redevelopment.jpg','The London, RLH, Whitechapel Hospital','The Royal London Hospital is a large teaching hospital in Whitechapel, East London, and is the flagship hospital of Barts Health NHS Trust, the largest NHS trust in England. Founded in 1740, it is one of the oldest hospitals in the country. The hospital is a major trauma centre for North East London and a specialist centre for emergency medicine, neurosurgery, and helicopter emergency services (London''s Air Ambulance is based on the roof). The Emergency Department handles over 130,000 attendances annually, making it one of the busiest A&E departments in the UK. The hospital moved into a new state-of-the-art building in 2012.','["Emergency Department (A&E)","Major Trauma Centre","London Air Ambulance","Neurosurgery","Critical Care","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Cardiac Care","Radiology"]','b5f9c496-4c12-46ca-90c6-83fbe6c189d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('0d212887-7eec-4abf-93da-504d7111a87a','Newham Hospital','newham-hospital','AE',NULL,'London','E13 8SL',NULL,NULL,51.51700000000000301,0.03500000000000000334,'London','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/4/4a/Newham_University_Hospital-_main_entrance_%28Geograph_1861636%29.jpg','Newham University Hospital, Newham General','Newham Hospital (also known as Newham University Hospital) is a district general hospital in Plaistow, East London. Part of Barts Health NHS Trust, the hospital serves one of the most diverse and densely populated communities in the UK. The Emergency Department operates 24/7 and handles approximately 85,000 attendances per year. The hospital provides a full range of acute services and has a dedicated Urgent Treatment Centre co-located with the A&E department. Newham Hospital has strong links with Queen Mary University of London and plays an important role in medical education and research.','["Emergency Department (A&E)","Urgent Treatment Centre","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Radiology","Pathology"]','b5f9c496-4c12-46ca-90c6-83fbe6c189d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('efef048a-3e0b-47a9-a3cd-f74b5dec9390','Whipps Cross Hospital','whipps-cross-hospital','AE',NULL,'London','E11 1NR',NULL,NULL,51.57000000000000028,0.008000000000000000166,'London','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/4/40/Whipps_Cross_Hospital_old_building.jpg','Whipps Cross University Hospital, Whipps Cross A&E','Whipps Cross Hospital is a district general hospital in Leytonstone, East London, part of Barts Health NHS Trust. The hospital serves the communities of Waltham Forest, Redbridge, and parts of neighbouring boroughs with a catchment population of approximately 350,000 people. The Emergency Department handles around 100,000 attendances annually and is consistently one of the busiest A&E departments in London. The hospital is currently undergoing a major redevelopment programme, with plans for a brand new hospital building. Despite its age, the hospital provides comprehensive acute services including maternity, paediatrics, and elderly care.','["Emergency Department (A&E)","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Elderly Care","Radiology","Pathology"]','b5f9c496-4c12-46ca-90c6-83fbe6c189d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('15203361-050b-478a-80dd-47ad275e9845','Queen Elizabeth Hospital Woolwich','queen-elizabeth-hospital-woolwich','AE',NULL,'London','SE18 4QH',NULL,NULL,51.48700000000000187,0.06700000000000000399,'London','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/0/07/Main_entrance%2C_Queen_Elizabeth_Hospital%2C_Woolwich.jpg','QEH Woolwich, Queen Elizabeth Greenwich','Queen Elizabeth Hospital (QEH) is a district general hospital in Woolwich, South East London, part of Lewisham and Greenwich NHS Trust. The hospital serves the Royal Borough of Greenwich and parts of Bexley with a catchment population of approximately 300,000. The Emergency Department provides 24-hour care and handles around 95,000 attendances per year. The hospital opened in 2001, replacing the former Brook Hospital, and is built using a PFI (Private Finance Initiative) model. QEH provides comprehensive acute services and has an on-site Urgent Treatment Centre to help manage non-emergency cases and reduce A&E pressure.','["Emergency Department (A&E)","Urgent Treatment Centre","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Critical Care","Radiology"]','0caf4aa4-98d9-4c06-82bd-c044b8f2f28c','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('faf669e1-b67e-4211-b15f-3a3c95df22e4','Queen Elizabeth Hospital Birmingham','queen-elizabeth-hospital-birmingham','AE',NULL,'Birmingham','B15 2GW',NULL,NULL,52.45100000000000051,-1.937999999999999945,'Birmingham & Solihull','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Queen_Elizabeth_Hospital_Birmingham%2C_Edgbaston%2C_Birmingham%2C_England-7March2011.jpg/960px-Queen_Elizabeth_Hospital_Birmingham%2C_Edgbaston%2C_Birmingham%2C_England-7March2011.jpg','QEHB, QE Birmingham, Queen Elizabeth Edgbaston','Queen Elizabeth Hospital Birmingham (QEHB) is one of the largest single-site hospitals in the UK, located in Edgbaston, Birmingham. Part of University Hospitals Birmingham NHS Foundation Trust, the hospital opened in 2010 and is a state-of-the-art facility with over 1,200 beds. QEHB is a major trauma centre for the West Midlands and hosts the Royal Centre for Defence Medicine, providing specialist care for military personnel. The Emergency Department is one of the busiest in England, handling over 150,000 attendances annually. The hospital is internationally renowned for its transplant programme and research capabilities.','["Emergency Department (A&E)","Major Trauma Centre","Royal Centre for Defence Medicine","Transplant Centre","Cardiac Surgery","Neurosurgery","Critical Care","Oncology","Haematology","Burns","Radiology"]','689d7ff7-c8be-420a-8bbc-99fda9fa4535','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('604b227d-428d-4095-ac6f-908aba5238d2','Heartlands Hospital','heartlands-hospital','AE',NULL,'Birmingham','B9 5SS',NULL,NULL,52.47399999999999665,-1.834000000000000074,'Birmingham & Solihull','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Heartlands_Hospital_and_Heartlands_Treatment_Centre.jpg/960px-Heartlands_Hospital_and_Heartlands_Treatment_Centre.jpg','Birmingham Heartlands, Heartlands A&E','Heartlands Hospital is a large district general hospital in Bordesley Green, East Birmingham. Part of University Hospitals Birmingham NHS Foundation Trust, the hospital serves the diverse communities of East Birmingham and Solihull. The Emergency Department handles approximately 110,000 attendances per year and has an on-site Urgent Treatment Centre. Heartlands is the designated centre for respiratory medicine in the Trust and has specialist units for heart failure, diabetes, and stroke. The hospital has strong academic links and is one of the largest employers in East Birmingham.','["Emergency Department (A&E)","Urgent Treatment Centre","Respiratory Medicine","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Cardiology","Stroke Unit","Radiology"]','689d7ff7-c8be-420a-8bbc-99fda9fa4535','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('73193731-17ee-4976-a6ec-b8af86636ccd','Good Hope Hospital','good-hope-hospital','AE',NULL,'Sutton Coldfield','B75 7RR',NULL,NULL,52.56700000000000017,-1.822000000000000063,'Birmingham & Solihull','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/6/60/Good_Hope_Hospital_-_geograph.org.uk_-_30692.jpg','Good Hope A&E, Sutton Coldfield Hospital','Good Hope Hospital is a district general hospital in Sutton Coldfield, North Birmingham. Part of University Hospitals Birmingham NHS Foundation Trust, the hospital serves the communities of Sutton Coldfield, Erdington, and parts of North Warwickshire. The Emergency Department handles approximately 75,000 attendances per year and operates 24 hours a day. Good Hope Hospital provides a wide range of acute services and has recently had significant investment in its emergency care facilities. The hospital is known for its strong community focus and dedicated clinical teams.','["Emergency Department (A&E)","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Elderly Care","Radiology","Pathology"]','689d7ff7-c8be-420a-8bbc-99fda9fa4535','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('1724ab99-2a03-46b3-9a6b-b043b13973d5','William Harvey Hospital','william-harvey-hospital','AE',NULL,'Ashford','TN24 0LZ',NULL,NULL,51.15699999999999648,0.8760000000000000008,'Kent','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/e/ea/William_Harvey_Hospital%2C_Main_Entrance_-_geograph.org.uk_-_1236142.jpg','WHH, William Harvey Ashford','William Harvey Hospital is a district general hospital in Ashford, Kent, part of East Kent Hospitals University NHS Foundation Trust. The hospital serves the communities of Ashford, Tenterden, and surrounding areas of East Kent. The Emergency Department provides 24-hour care and handles approximately 65,000 attendances per year. The hospital is a specialist centre for vascular surgery in East Kent and provides a full range of acute services. Named after the 17th-century physician William Harvey who discovered blood circulation, the hospital maintains strong links with Kent and Canterbury Christ Church University.','["Emergency Department (A&E)","Vascular Surgery","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Cardiology","Radiology"]','e272356c-c9d0-49be-8b12-337ad08c0e61','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('65ea7cb8-d945-4530-a5d2-91d8c5907376','Maidstone Hospital','maidstone-hospital','AE',NULL,'Maidstone','ME16 9QQ',NULL,NULL,51.26700000000000301,0.5080000000000000071,'Kent','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/7/7f/Maidstone_Hospital.JPG','Maidstone A&E, Maidstone General','Maidstone Hospital is a district general hospital in Maidstone, the county town of Kent. Part of Maidstone and Tunbridge Wells NHS Trust, the hospital provides acute and specialist services to a population of approximately 500,000 across West Kent and parts of East Sussex. The Emergency Department handles around 80,000 attendances per year and includes a co-located Urgent Treatment Centre. The hospital is the Trust''s centre for cancer services, oncology, and specialist diagnostics. The site has undergone significant investment in recent years, including a new emergency care centre.','["Emergency Department (A&E)","Urgent Treatment Centre","Cancer Centre","Oncology","Acute Medicine","General Surgery","Orthopaedics","Radiology","Pathology"]','e272356c-c9d0-49be-8b12-337ad08c0e61','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('94eb710b-177d-46a4-abc2-13ca97163485','Craigavon Area Hospital','craigavon-area-hospital','AE',NULL,'Craigavon','BT63 5QQ',NULL,NULL,54.44400000000000261,-6.392999999999999794,'Northern Ireland','Northern Ireland','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/0/08/Craigavon_Area_Hospital_-_Front_Entrance_-_geograph.org.uk_-_1401867.jpg','Craigavon Hospital, CAH','Craigavon Area Hospital is the main acute hospital for the Southern Health and Social Care Trust, located in Craigavon, County Armagh. The hospital serves a population of approximately 350,000 across the Southern Trust area including Armagh, Dungannon, Banbridge, and Newry. The Emergency Department handles approximately 70,000 attendances per year and provides 24-hour emergency care. Craigavon Area Hospital is a modern facility that has been significantly expanded and refurbished in recent years, with new acute services block and improved emergency department facilities.','["Emergency Department (A&E)","Acute Medicine","General Surgery","Orthopaedics","Paediatrics","Maternity","Cardiology","Respiratory Medicine","Radiology"]','dec3042d-5ef8-441f-ad61-75e2e70619c0','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('d7d73198-1a27-4c7f-b78d-a5128a2ad9b3','Forth Valley Royal Hospital','forth-valley-royal-hospital','AE',NULL,'Larbert','FK5 4WR',NULL,NULL,56.0279999999999987,-3.813000000000000166,'Scotland','Scotland','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/1/17/Forth_Valley_Royal_close.jpg','FVRH, Larbert Hospital','Forth Valley Royal Hospital is a state-of-the-art acute hospital in Larbert, near Falkirk, Scotland. Part of NHS Forth Valley, the hospital opened in 2011 and replaced the Royal Scottish National Hospital and Falkirk & District Royal Infirmary. It serves a population of approximately 300,000 across the Forth Valley area including Falkirk, Stirling, and Clackmannanshire. The Emergency Department handles approximately 65,000 attendances per year. The hospital is one of the most modern in Scotland and features single-room accommodation for all inpatients, a dedicated assessment unit, and comprehensive diagnostic facilities.','["Emergency Department (A&E)","Acute Medical Unit","Critical Care","General Surgery","Orthopaedics","Paediatrics","Maternity","Cardiology","Stroke Unit","Radiology"]','fe4e413e-4830-4502-972c-6946f7cf9f9b','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('22620765-b02d-4722-8776-dfd2f13f0dcb','Manchester Royal Infirmary','manchester-royal-infirmary','AE',NULL,'Manchester','M13 9WL','0161 276 1234',NULL,53.46099999999999853,-2.225999999999999979,'North West','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/9/96/Manchester-Royal-Infirmary-Main-Entrance.JPG','MRI, Manchester Royal, MRI A&E','Manchester Royal Infirmary (MRI) is a major teaching hospital in central Manchester, part of Manchester University NHS Foundation Trust, the largest NHS trust in England. The hospital is a major trauma centre for Greater Manchester and provides specialist services in transplantation, renal medicine, and infectious diseases. The Emergency Department handles over 130,000 attendances annually, making it one of the busiest in the country. MRI has strong academic links with the University of Manchester and is at the forefront of medical research and innovation. The hospital is part of the Manchester Royal campus alongside Saint Mary''s Hospital and the Royal Manchester Children''s Hospital.','["Emergency Department (A&E)","Major Trauma Centre","Transplant Centre","Renal Medicine","Infectious Diseases","Critical Care","Acute Medicine","General Surgery","Cardiology","Radiology"]','3decef29-77a1-4312-a143-98d444ff5296','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('c0190083-238f-4394-9fb0-ae0488feac8e','Leeds General Infirmary','leeds-general-infirmary','AE',NULL,'Leeds','LS1 3EX','0113 243 2799',NULL,53.80199999999999961,-1.552999999999999937,'Yorkshire','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/2/25/Jubilee_wing%2C_Leeds_General_Infirmary.jpg','LGI, Leeds General, LGI A&E','Leeds General Infirmary (LGI) is a large teaching hospital in central Leeds, West Yorkshire. Part of Leeds Teaching Hospitals NHS Trust, one of the largest trusts in Europe, the hospital is a major trauma centre for West Yorkshire and provides specialist services in neurosurgery, cardiac surgery, and paediatric intensive care. The Emergency Department handles over 120,000 attendances per year. LGI has strong academic links with the University of Leeds and is a leading centre for clinical research. The hospital serves a population of approximately 780,000 for core services and up to 5.4 million for specialist services.','["Emergency Department (A&E)","Major Trauma Centre","Neurosurgery","Cardiac Surgery","Paediatric Intensive Care","Critical Care","Acute Medicine","General Surgery","Radiology"]','4a5a288d-21b7-44b9-9d79-3c69b00856c6','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('c7d5d632-1ea5-468f-be88-2a1830a5e526','Royal Victoria Infirmary Newcastle','royal-victoria-infirmary-newcastle','AE',NULL,'Newcastle upon Tyne','NE1 4LP','0191 233 6161',NULL,54.98100000000000164,-1.618999999999999995,'North East','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/5/5a/Peacock_Hall%2C_Royal_Victoria_Infirmary_-_geograph.org.uk_-_1762074.jpg','RVI, RVI Newcastle, Newcastle Royal','The Royal Victoria Infirmary (RVI) is a major teaching hospital in central Newcastle upon Tyne. Part of Newcastle upon Tyne Hospitals NHS Foundation Trust, consistently rated as one of the best trusts in England, the hospital is a major trauma centre for the North East and provides specialist services in transplantation, cardiothoracic surgery, and paediatrics. The Emergency Department handles approximately 95,000 attendances per year. The RVI has strong links with Newcastle University and is renowned for its medical research. The Great North Children''s Hospital, which provides specialist paediatric services for the region, is located on the RVI site.','["Emergency Department (A&E)","Major Trauma Centre","Great North Children''s Hospital","Transplant Centre","Cardiothoracic Surgery","Critical Care","Acute Medicine","Neurology","Radiology"]','685f0885-5a5c-4e59-a43e-52a4f80cf2d2','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('7a3dc85d-384d-4603-93f9-9dc65735aac2','Bristol Royal Infirmary','bristol-royal-infirmary','AE',NULL,'Bristol','BS2 8HW','0117 923 0000',NULL,51.45900000000000318,-2.591000000000000191,'South West','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/7/7a/Bristol_Royal_Infirmary.jpg','BRI, Bristol Royal, BRI A&E','Bristol Royal Infirmary (BRI) is a large teaching hospital in the centre of Bristol. Part of University Hospitals Bristol and Weston NHS Foundation Trust, the hospital is a major trauma centre for the Severn area and provides specialist services in cardiac surgery, neurosurgery, and vascular surgery. The Emergency Department handles approximately 90,000 attendances per year. The BRI has strong academic links with the University of Bristol and is a leading centre for clinical research and medical education. The hospital campus is adjacent to Bristol Royal Hospital for Children, which provides specialist paediatric services for the region.','["Emergency Department (A&E)","Major Trauma Centre","Cardiac Surgery","Neurosurgery","Vascular Surgery","Critical Care","Acute Medicine","General Surgery","Oncology","Radiology"]','8d4e0011-77a4-4c1d-ad6f-591be682b4e0','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('cd9cd0bf-0a83-4ec5-ab4b-b5b33e7e51f7','Queen''s Medical Centre Nottingham','queens-medical-centre-nottingham','AE',NULL,'Nottingham','NG7 2UH','0115 924 9924',NULL,52.94299999999999784,-1.183999999999999942,'Midlands','England','Open: 24 hours, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/4/4d/QMC_%28Queens_Medical_Centre%29_-_geograph.org.uk_-_680969.jpg','QMC, Queen''s Med, QMC Nottingham','Queen''s Medical Centre (QMC) is one of the largest teaching hospitals in the UK, located in Nottingham. Part of Nottingham University Hospitals NHS Trust, the hospital is a major trauma centre for the East Midlands and provides specialist services in neurosurgery, stroke, and paediatric intensive care. The Emergency Department is one of the busiest in England, handling over 130,000 attendances per year. The hospital is closely linked with the University of Nottingham and is a leading centre for medical research. QMC also houses the East Midlands Major Trauma Centre and the Nottingham Children''s Hospital.','["Emergency Department (A&E)","Major Trauma Centre","East Midlands Trauma Centre","Neurosurgery","Stroke Centre","Paediatric Intensive Care","Critical Care","Acute Medicine","General Surgery","Radiology"]','e48ace20-5c1e-4fcd-b149-c2f98a034797','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('73355101-f0c4-4916-97c0-c2558745b0d0','Homerton Urgent Treatment Centre','homerton-urgent-treatment-centre','UTC',NULL,'London','E9 6SR',NULL,NULL,51.54800000000000181,-0.04299999999999999655,'London','England','Open: 8am - 10pm, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/1/12/Homerton_Hospital%2C_Hackney_-_geograph.org.uk_-_724458.jpg','Homerton UTC, Homerton Walk-in','Homerton Urgent Treatment Centre provides walk-in care for non-life-threatening conditions such as minor injuries, sprains, minor burns, and infections. The centre is staffed by experienced clinicians and can handle a wide range of conditions that do not require a full A&E department. Patients are triaged on arrival and seen in order of clinical priority. The UTC can provide X-rays, blood tests, and minor procedures. If you are unsure whether you need A&E or a UTC, calling NHS 111 can help you decide. UTCs are typically much faster than A&E for minor conditions.','["Urgent Treatment Centre","Minor Injuries","X-ray","Pharmacy"]','b5f9c496-4c12-46ca-90c6-83fbe6c189d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
INSERT OR IGNORE INTO hospitals VALUES('d347142e-5f44-4728-a2ce-013778049c91','Edgware Urgent Treatment Centre','edgware-urgent-treatment-centre','UTC',NULL,'London','HA8 0AD',NULL,NULL,51.61299999999999955,-0.2750000000000000222,'London','England','Open: 8am - 8pm, 7 days a week','https://upload.wikimedia.org/wikipedia/commons/9/97/Edgware_Community_Hospital_-_geograph.org.uk_-_2290737.jpg','Edgware UTC, Edgware Walk-in Centre','Edgware Urgent Treatment Centre provides same-day care for urgent but non-life-threatening conditions. The centre handles conditions such as cuts, minor fractures, sprains, skin infections, and urinary tract infections. It is an alternative to A&E for conditions that need prompt attention but are not emergencies. The UTC is staffed by GPs and emergency nurse practitioners who can prescribe medication, order X-rays, and refer to hospital specialists if needed.','["Urgent Treatment Centre","Minor Injuries","X-ray"]','b5f9c496-4c12-46ca-90c6-83fbe6c189d9','2026-09-09 06:59:14','2026-09-09 06:59:14');
