INSERT OR IGNORE INTO hospitals VALUES('0b71abdb-b67f-440e-b408-140fb3b8220b','Mater Hospital','mater-hospital','AE',NULL,'Belfast',NULL,NULL,NULL,54.60410000000000252,-5.929400000000000225,'Northern Ireland','Northern Ireland','Open: 24 hours, 7 days a week','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Mater_Infirmorum_Hospital.png/960px-Mater_Infirmorum_Hospital.png',NULL,NULL,NULL,'5263a62b-29ad-4273-898d-318bda318a9a','2026-09-09 18:32:35','2026-09-09 18:32:35');
INSERT OR IGNORE INTO hospitals VALUES('d2d86a57-70b9-457d-a713-60a241ebad5f','Royal Victoria Hospital','royal-victoria-hospital','AE',NULL,'Belfast',NULL,NULL,NULL,54.59559999999999747,-5.914500000000000312,'Northern Ireland','Northern Ireland','Open: 24 hours, 7 days a week',NULL,NULL,'The Royal Victoria Hospital (RVH) is a major teaching hospital in the Falls Road area of Belfast, Northern Ireland. Part of Belfast Health and Social Care Trust, the hospital is one of the busiest emergency departments in Northern Ireland, handling over 100,000 attendances per year. The RVH is the regional trauma centre for Northern Ireland and provides specialist services including neurosurgery, cardiac surgery, and burns care. The hospital has undergone massive redevelopment with new critical care facilities and a modern emergency department. It has strong academic links with Queen''s University Belfast.',NULL,'5263a62b-29ad-4273-898d-318bda318a9a','2026-09-09 18:32:35','2026-09-09 18:32:35');
