INSERT OR IGNORE INTO hospitals VALUES('74f8353d-c49f-4dcb-ae3b-4fb1f824b70c','Ulster Hospital','ulster-hospital','AE',NULL,'Dundonald',NULL,NULL,NULL,54.59389999999999788,-5.799000000000000376,'Northern Ireland','Northern Ireland','Open: 24 hours, 7 days a week',NULL,NULL,'The Ulster Hospital is a large acute hospital in Dundonald, on the outskirts of Belfast, part of the South Eastern Health and Social Care Trust. The hospital serves a population of approximately 350,000 across the greater Belfast area, North Down, Ards, and Lisburn. The Emergency Department handles over 90,000 attendances per year and is one of the busiest in Northern Ireland. The hospital has undergone a phased redevelopment programme including a new inpatient ward block and refurbished emergency care facilities. The Ulster Hospital provides comprehensive acute services and is a key hospital for the eastern region.',NULL,'5263a62b-29ad-4273-898d-318bda318a9a','2026-09-09 18:32:35','2026-09-09 18:32:35');
