INSERT OR IGNORE INTO hospitals VALUES('e49c2b58-6ba4-410a-b56e-9656e714f321','University Hospital Coventry','university-hospital-coventry','AE',NULL,'Coventry',NULL,NULL,NULL,52.4200000000000017,-1.439999999999999947,'Midlands','England',NULL,NULL,NULL,NULL,NULL,'42420547-5da9-4f63-8abb-cdeaccdf434f','2026-09-09 18:46:49','2026-09-09 18:46:49');
INSERT OR IGNORE INTO hospitals VALUES('e297d607-ffd3-41de-b307-0b667f179c7c','Derriford Hospital','derriford-hospital','AE',NULL,'Plymouth',NULL,NULL,NULL,50.41599999999999682,-4.113000000000000434,'South West','England',NULL,'https://upload.wikimedia.org/wikipedia/commons/e/e2/Derriford_Hospital.jpg',NULL,'Derriford Hospital is the largest hospital in the South West Peninsula, located in the Derriford area of Plymouth, Devon. Part of University Hospitals Plymouth NHS Trust, the hospital is a major trauma centre for Devon, Cornwall, and the Isles of Scilly, serving a population of approximately 450,000 for local services and 2 million for specialist care. The Emergency Department handles over 100,000 attendances per year. Derriford is a teaching hospital with links to Plymouth University and is a major centre for neurosurgery, cardiothoracic surgery, and kidney transplantation. The hospital has approximately 900 beds.',NULL,'b98337ea-8b6c-4210-ab98-0dcc7f3a658c','2026-09-09 18:46:51','2026-09-09 18:46:51');
