INSERT OR IGNORE INTO hospitals VALUES('0d7ecca2-bb5c-4d05-a60a-78737cd8d60e','QEQM Hospital Margate','qeqm-hospital-margate','UTC',NULL,'Margate',NULL,NULL,NULL,51.37460000000000093,1.385599999999999943,'Kent','England',NULL,'https://upload.wikimedia.org/wikipedia/commons/8/8a/QEQM_Hospital%2C_Margate_-_geograph.org.uk_-_991371.jpg',NULL,'The Queen Elizabeth the Queen Mother Hospital (QEQM) is a district general hospital in Margate, Kent, part of East Kent Hospitals University NHS Foundation Trust. The hospital serves the communities of Thanet and surrounding areas of East Kent. The Emergency Department handles approximately 60,000 attendances per year and operates 24 hours a day. QEQM provides a range of acute services and is the main emergency hospital for the Thanet area. The hospital has close links with Canterbury Christ Church University and plays an important role in training healthcare professionals in East Kent.',NULL,'8221ab66-8b86-44e5-acc9-4c4f552f9690','2026-09-09 18:49:55','2026-09-09 18:49:55');
